'use strict';
import {educatorResources,nickToolkitUrl} from './educatorResources.js';
const $ = (s,root=document)=>root.querySelector(s);
const $$ = (s,root=document)=>Array.from(root.querySelectorAll(s));
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={notes:{},done:new Set(),answers:{},skill:'Thinking',practice:0,programme:'MYP',checks:{},focus:false};
const noteLabels={unit:'Current unit and task',learning:'What students will understand or do',question:'Inquiry question',evidence:'Evidence and success criterion',limit:'A limitation in the fictional model',responsibility:'Programme reference and requirement to verify',revision:'Revised task directions',atl:'ATL practice to teach and observe',tok:'Question about knowledge',feedback:'Partner challenge and response',change:'What changed and why',trial:'Teaching date, evidence and review date',tech:'Technology purpose and independent student thinking',review:'What I verified, changed or rejected',permissions:'Task permission, disclosure and no-AI route',support:'Non-identifying classroom support and review evidence',confidence:'One responsibility I am clearer about / one question to resolve'};
const steps=[
 {id:'start',title:'Choose your unit',sub:'5 min',goal:'One real task to improve',atl:'Communication',tok:'What would count as evidence of learning?'},
 {id:'evidence',title:'Test a claim',sub:'10 min',goal:'Separate evidence from inference',atl:'Thinking + research',tok:'When does a pattern justify a claim?'},
 {id:'responsibilities',title:'Check programme guidance',sub:'5 min',goal:'Name the right programme reference',atl:'Research + self-management',tok:'Which authority justifies this judgment?'},
 {id:'studio',title:'Revise the task',sub:'20 min',goal:'One revised task in your current unit',atl:'Choose one observable practice',tok:'How is knowledge justified in this subject?'},
 {id:'challenge',title:'Invite a challenge',sub:'10 min',goal:'Feedback that changes the thinking',atl:'Communication + social',tok:'What evidence would change your view?'},
 {id:'commit',title:'Revise & try',sub:'10 min',goal:'A revision and a classroom trial',atl:'Self-management',tok:'How has feedback changed what you know?'},
 {id:'technology',title:'Technology lab',sub:'60 min',goal:'Choose a tool for a learning purpose',atl:'Thinking + research',tok:'Who is responsible for an AI-assisted claim?'},
 {id:'support',title:'Support & reflect',sub:'30 min',goal:'A careful, reviewable classroom support',atl:'Research + social',tok:'What must we check before acting?'}
];
const urls={school:'https://arroyovalley.sbcusd.com/academies/global-leadership-academy',teaching:'https://www.ibo.org/benefits/the-ib-teaching-style/',education:'https://ibo.org/professional-development/free-learning/what-is-an-ib-education/',myp:'https://www.ibo.org/programmes/middle-years-programme/curriculum/',mypAssessment:'https://www.ibo.org/programmes/middle-years-programme/assessment-and-exams/',dp:'https://www.ibo.org/programmes/diploma-programme/curriculum/',tok:'https://ibo.org/programmes/diploma-programme/curriculum/dp-core/theory-of-knowledge/what-is-tok/',ai:'https://www.ibo.org/programmes/artificial-intelligence-ai-in-learning-teaching-and-assessment',integrity:'https://ibo.org/about-the-ib/what-it-means-to-be-an-ib-student/responsibilities-of-students-and-ib-world-schools/academic-integrity/'};
const ext=(url,text,cls='')=>`<a class="${cls}" href="${url}" target="_blank" rel="noopener">${text} <span aria-hidden="true">→</span><span class="sr-only"> (opens a new tab)</span></a>`;
const resourceCollection=r=>r.collection||(r.internal?'Studio tools':'Official IB');
const resources=[
 {title:'What is an IB education?',topic:'Foundations',type:'Interactive learning',desc:'The IB’s public learning collection, including teacher inquiries and short explorations of inquiry, inclusion, and ATL.',url:urls.education},
 {title:'The IB teaching style',topic:'Foundations',type:'Official overview',desc:'A concise introduction to learner-centered teaching, inquiry, action, reflection, and international contexts.',url:urls.teaching},
 {title:'MYP curriculum',topic:'MYP',type:'Official overview',desc:'Start with subject groups, conceptual understanding, global contexts, and ATL. Follow the page’s subject links for subject briefs.',url:urls.myp},
 {title:'MYP assessment & exams',topic:'MYP',type:'Official guidance',desc:'Clarifies school-based assessment against subject-group objectives and criteria, and distinguishes optional external assessment.',url:urls.mypAssessment},
 {title:'DP curriculum',topic:'DP',type:'Official overview',desc:'Locate the subject groups and DP core. Use your current subject guide for detailed aims, assessment requirements, and course decisions.',url:urls.dp},
 {title:'What is theory of knowledge?',topic:'TOK',type:'Official overview',desc:'Understand TOK’s role in the DP core and its focus on how knowledge claims are made and justified.',url:urls.tok},
 {title:'AI in learning, teaching & assessment',topic:'Technology',type:'Official guidance',desc:'IB guidance on critical review, attribution, and integrity. Includes links to sample TOK activities and the academic integrity policy.',url:urls.ai},
 {title:'Academic integrity',topic:'Technology',type:'Official guidance',desc:'A starting point for authentic work, transparent acknowledgment, and responsible academic choices.',url:urls.integrity},
 {title:'The current-unit task studio',topic:'Workshop tools',type:'Interactive activity',desc:'Turn one existing task into a clearer inquiry with evidence, an observable ATL practice, a knowledge question, and feedback.',url:'#workshop/studio',internal:true},
 {title:'Fictional claim critique',topic:'Workshop tools',type:'Interactive activity',desc:'Test three claims against a small fictional dataset. Compare a pattern with unsupported claims about safety and cause.',url:'#workshop/evidence',internal:true},
 {title:'Three technology practice cards',topic:'Workshop tools',type:'Reusable routines',desc:'Try criteria and feedback, language access, or storyboard critique. Every card includes teacher checks and a no-AI route.',url:'#workshop/technology',internal:true},
 {title:'A careful support conversation',topic:'Workshop tools',type:'PLC protocol',desc:'Notice evidence, verify context, choose a low-risk classroom support, and define review evidence. No student records are stored here.',url:'#workshop/support',internal:true}
];
resources.push(
 {title:'MYP unit planning resources',topic:'MYP',type:'Official professional learning',desc:'Public IB webinars and partially completed unit planners. Use alongside the current subject guide and school template.',url:'https://www.ibo.org/professional-development/free-learning/myp-pd-learning-resources/myp-eassessment-webinar-series/'},
 {title:'MYP personal project',topic:'MYP',type:'Official overview',desc:'The process, product or outcome, reflective report, supervision, and moderation.',url:'https://www.ibo.org/programmes/middle-years-programme/assessment-and-exams/personal-project/'},
 {title:'Personal project nano professional learning',topic:'MYP',type:'Free professional learning',desc:'Short IB professional learning resources for supporting the personal project.',url:'https://www.ibo.org/professional-development/free-learning/myp-pd-learning-resources/myp-nano-resources/'},
 {title:'MYP unit organizer & ATL connections',topic:'Workshop tools',type:'Interactive organizer',desc:'An adaptable unit structure with in-tab working notes, download, and practical connections to ATL and the personal project.',url:'#myp',internal:true},
 {title:'DP core pathways',topic:'DP',type:'Programme connections',desc:'A starting point for TOK, extended essay, and CAS with clear distinctions between subject connections and core requirements.',url:'#core',internal:true}
);
resources.push(...educatorResources);
resources.push({title:'Subject-group recruitment activity',topic:'Workshop tools',type:'Guided group discussion',desc:'Discuss two or three concrete subject benefits for college, career, or life; craft one student-facing sentence; record a group response and share a brief report-out. Use the in-tab scratchpad and download your draft.',url:'#recruitment',internal:true});
resources.push({title:'Past PD & PLC resources',topic:'Professional learning',type:'Curated archive',desc:'Find PD, IB PLC and academy meetings by date. Open teaching activities, revisit previous session summaries and download a working agenda. Private records are not included.',url:'#pd/archive',internal:true});
resources.push({title:'Personal project supervisor & lead tools',topic:'MYP',type:'Criterion-aligned preparation',desc:'Original criterion summaries, coaching questions, meeting preparation and lead-teacher checklists. No student records or private source documents.',url:'#pp',internal:true});
resources.push({title:'Education research reading room',topic:'Education research',type:'Source-linked research briefs',desc:'Explore peer-reviewed articles, research data, evidence limits, and secondary-classroom connections to inquiry and ATL. Build a reading list and plan a small teaching change.',url:'#research',internal:true});
const field=(id,label,hint='',rows=3)=>`<label class="field"><span>${label}</span>${hint?`<small>${hint}</small>`:''}<textarea data-note="${id}" rows="${rows}" placeholder="Write a brief, non-identifying note…">${escapeHTML(state.notes[id]||'')}</textarea></label>`;
const tile=(n,title,body)=>`<div class="task-tile"><span class="number">${n}</span><h3>${title}</h3><p>${body}</p></div>`;
function home(){return `<div class="shell"><section class="hero"><div><p class="eyebrow">GLOBAL LEADERSHIP · PROFESSIONAL LEARNING</p><h1>Big questions.<br>Visible thinking.<br><em>Purposeful teaching.</em></h1><p class="intro">A growing home for IB learning at Arroyo Valley. Connect the ideas behind the programme to the unit you are teaching, the questions students ask, and the evidence you see.</p><div class="actions"><a class="btn" href="#pd">Explore teacher learning <span aria-hidden="true">→</span></a><a class="text-link" href="#ib">Get oriented to IB</a></div></div><div class="learning-map" aria-label="Our workshop approach: ask a question, examine evidence, explain, then reflect and revise"><div class="map-top"><span>THE LEARNING STUDIO</span><span>01 / INQUIRY</span></div><span class="map-circle" aria-hidden="true"></span><p class="map-question">What changes when we make the thinking visible?</p><div class="cycle"><span>Question</span><b>→</b><span>Evidence</span><b>→</b><span>Explanation</span><b>↻</b></div><div class="map-footer"><span class="asterisk" aria-hidden="true">✳</span><span>Make a claim. Invite a challenge.<br>Reflect, revise, and try again.</span></div></div></section><section class="feature-strip"><div><p class="eyebrow">REUSABLE TEACHER WORKSHOP</p><h3>Bring one unit. Leave with one stronger task.</h3><p>An interactive working session for inquiry, ATL, TOK connections, and purposeful technology.</p></div><a class="btn" href="#workshop/start">Open the workshop <span aria-hidden="true">→</span></a></section><div class="section-head"><h2>Find your way in.</h2><p>Start with the programme, work with a colleague, or pick a resource for your next lesson.</p></div><div class="grid3"><article class="card"><span class="num">01</span><h3><a href="#ib">Understand your IB role →</a></h3><p>MYP and DP have shared foundations and distinct requirements. Find the right starting point and questions to bring to your subject guide.</p></article><article class="card"><span class="num">02</span><h3><a href="#pd">Learn together →</a></h3><p>A dedicated PD and PLC home, with a usable workshop now and room for future sessions, artifacts, and reflection.</p></article><article class="card"><span class="num">03</span><h3><a href="#resources">Keep useful resources close →</a></h3><p>A searchable first collection of official public IB sources and practical classroom tools, organized by purpose.</p></article></div><div class="section-head"><h2>Growing with the programme.</h2><p>This first collection emphasizes teacher learning. The wider school-facing sections will be reviewed before public use.</p></div><div class="grid3"><div class="card"><span class="badge draft">PLANNED · NOT YET PUBLISHED</span><h3 style="margin-top:18px">Students &amp; families</h3><p>Clear pathways, programme expectations, frequently asked questions, and where to find support.</p></div><div class="card"><span class="badge draft">PLANNED · NEEDS SCHOOL REVIEW</span><h3 style="margin-top:18px">Programme information</h3><p>Current course offerings, school policies, dates, and contacts verified by the programme team.</p></div><div class="card"><span class="badge draft">PLANNED · PERMISSION REQUIRED</span><h3 style="margin-top:18px">Learning in action</h3><p>Selected examples of student inquiry and teacher practice, shared only with appropriate permission.</p></div></div></div>`;}
function ib(){return `<div class="shell"><div class="page-title"><p class="eyebrow">ABOUT IB · A SHARED FOUNDATION</p><h1>Know the programme.<br>Teach your subject well.</h1><p>IB teaching connects disciplinary understanding with inquiry and reflection. The practical starting point is your current unit: its learning goals, the evidence students will produce, and the skills you will teach explicitly.</p></div><div class="grid2"><article class="card"><p class="eyebrow">MIDDLE YEARS PROGRAMME</p><h2>MYP</h2><p>Use concepts and a meaningful global context to give the unit direction. Connect the task to the relevant subject-group objectives and year-level assessment criteria.</p><dl class="definition-list"><dt>Keep in view</dt><dd>The current unit planner, appropriate subject guidance, ATL practice, and access to the intended learning.</dd><dt>A question to ask</dt><dd>Where will students use this concept, and what in their work will show the intended understanding?</dd><dt>TOK connection</dt><dd>Questions about evidence and perspective can enrich inquiry. MYP does not require the DP TOK course.</dd></dl><div class="actions">${ext(urls.myp,'MYP curriculum','text-link')}${ext(urls.mypAssessment,'MYP assessment','text-link')}</div></article><article class="card"><p class="eyebrow">DIPLOMA PROGRAMME</p><h2>DP</h2><p>Anchor the task in the relevant subject aims, content, assessment requirements, and current guide. Make a fitting connection to how knowledge is developed in the discipline.</p><dl class="definition-list"><dt>Keep in view</dt><dd>Your current subject guide and course plan, assessment expectations, and an intentional ATL practice.</dd><dt>A question to ask</dt><dd>What makes a conclusion convincing in this subject, and where are its limits?</dd><dt>TOK connection</dt><dd>TOK is part of the DP core. A subject connection can strengthen learning without turning every lesson into a formal TOK assessment.</dd></dl><div class="actions">${ext(urls.dp,'DP curriculum','text-link')}${ext(urls.tok,'What is TOK?','text-link')}</div></article></div><div class="note" style="margin-top:24px"><strong>A starting point, not a compliance checklist.</strong> Public summaries do not replace current subject guides, school policies, or coordinator guidance. Programme details and local requirements should be checked before making assessment or course decisions.</div><div class="section-head"><h2>Make ATL observable.</h2><p>Approaches to learning are skills students practice. Choose a specific action you can teach, notice, and revisit.</p></div><div class="card"><div class="skill-buttons">${skillButtons()}</div><div class="skill-detail" id="skill-detail">${skillDetail()}</div><p class="small muted" style="margin-top:18px">Examples are workshop suggestions. ${ext(urls.education,'Explore the IB’s public ATL learning resources')}.</p></div><div class="callout-big"><h3>A useful knowledge question goes beyond the answer.</h3><p>Try: “What evidence would justify this conclusion?” or “How does the representation shape what we notice?” Keep the question connected to the actual work of your subject.</p><a class="btn light" href="#workshop/studio">Apply it to your unit →</a></div><p class="small muted">For AP and other courses, retain your existing standards and assessment requirements. You can adapt the inquiry routines and knowledge questions without adding formal IB requirements.</p></div>`;}
const skills={Thinking:['Compare, challenge, revise','Students distinguish a supported claim from an assumption, then revise their explanation.'],Research:['Check the evidence','Students examine the source, method, and limits of the information behind a claim.'],Communication:['Make reasoning clear','Students explain a choice and respond to a partner’s question with a reason.'],Social:['Build on a challenge','Partners listen, paraphrase a different view, and use it to improve their work.'],'Self-management':['Use a checkpoint','Students pause against a criterion, name a gap, and keep a short revision record.']};
function skillButtons(){return Object.keys(skills).map(s=>`<button class="skill-button" data-skill="${s}" aria-pressed="${state.skill===s}">${s}</button>`).join('');}
function skillDetail(){const v=skills[state.skill];return `<h4>${v[0]}</h4><p>${v[1]}</p>`;}
function pd(){return `<div class="shell"><div class="page-title"><p class="eyebrow">TEACHER LEARNING · PD &amp; PLC</p><h1>One place to learn,<br>practice, and return.</h1><p>Turn professional learning into a clearer task, a classroom trial, and evidence worth discussing next time.</p><div class="actions"><a class="text-link" href="#research">Explore education research →</a><a class="text-link" href="#pd/archive">Browse past PD &amp; PLC resources →</a></div></div><section class="recruitment-route-banner glass"><div><span class="pill blue">SUBJECT GROUPS · 7 MINUTES</span><h2>Make the subject’s value clear.</h2><p>Discuss 2–3 benefits for college, career, or life. Craft one sentence for prospective students, download your draft, and share a brief report-out.</p></div><a class="btn gold" href="#recruitment">Open recruitment activity →</a></section><section class="session-feature"><div class="session-intro"><span class="badge">REUSABLE WORKSHOP</span><h2>Make thinking visible.</h2><p>Bring a current unit and one task to improve. Work through inquiry, programme responsibilities, an ATL practice, and a question about knowledge. Extend the same work in the technology lab.</p><div class="actions"><a class="btn gold" href="#workshop/start">Enter interactive workshop →</a><a class="btn light" href="#workshop/technology">Technology lab</a></div><p class="session-note">Work at your own pace. No sign-up or AI account is needed for these activities.</p></div><div class="session-detail"><p class="eyebrow">A FLEXIBLE WORKING SEQUENCE</p><ol><li>Choose a current task and check its purpose.</li><li>Examine evidence and programme expectations.</li><li>Revise, invite feedback, and plan a classroom trial.</li><li>Choose purposeful technology and careful support.</li></ol><p>Suggested durations are planning aids, not an official school schedule.</p></div></section></div>`;}

function resourcePage(){return `<div class="shell"><div class="page-title"><p class="eyebrow">THE RESOURCE COLLECTION</p><h1>Resource library</h1><p>Search official IB guidance, teaching tools and educator resources. Each item links to its source.</p></div><div class="resource-download-link"><a href="#downloads">Blank fillable planning forms →</a><a href="#pd/archive">Past PD &amp; PLC materials →</a><button class="text-link" data-action="nick-collection">Nick’s shared toolkit →</button></div><div class="filters"><div><label for="resource-search">Search resources</label><input id="resource-search" type="search" placeholder="Try inquiry, assessment, AI, ATL, or Nick…" autocomplete="off"></div><div><label for="resource-collection">Collection</label><select id="resource-collection"><option>All collections</option>${[...new Set(resources.map(resourceCollection))].map(c=>`<option>${escapeHTML(c)}</option>`).join('')}</select></div><div><label for="resource-topic">Topic</label><select id="resource-topic"><option>All topics</option>${[...new Set(resources.map(r=>r.topic))].map(t=>`<option>${t}</option>`).join('')}</select></div></div><p class="small muted" id="resource-count" role="status" aria-live="polite"></p><div class="resource-grid" id="resource-grid"></div><section class="resource-feature" aria-labelledby="nick-collection-title"><span class="badge educator-source">EDUCATOR COLLECTION · FOR REVIEW</span><h2 id="nick-collection-title">Nick’s shared toolkit</h2><p>Selected tools from <em>AI Tools for Teachers: Your Simple Guide</em>, shared by Nicholas Cherms. Our summaries link to the original sites; classroom suggestions are not official IB guidance.</p><p><strong>Check before classroom use.</strong> Inclusion here does not mean district approval. Review privacy, age requirements, accessibility, permitted assistance, and current school policy. Use fictional or teacher-authored examples; keep student and confidential information out.</p><div class="actions"><button class="btn secondary" data-action="nick-collection">Browse this collection →</button>${ext(nickToolkitUrl,'Open Nick’s full guide','text-link')}</div></section><div class="note" style="margin-top:28px"><strong>Source and access notes.</strong> Sources were reviewed November 8, 2026. Official IB guidance and third-party educator resources are labeled separately. Links and short summaries preserve the original source; no licensed teacher materials or private correspondence are copied here. Linked documents keep their original access settings. A listing is not district approval. Check tool access, age requirements, privacy, accessibility, and current school policy before classroom use. Never enter student or confidential information into an unapproved service.</div><div class="resource-next"><a href="#pd/archive">Past PD &amp; PLC materials →</a><a href="#downloads">Blank planning forms →</a></div></div>`;}
function updateResources(){
 const q=($('#resource-search')?.value||'').toLowerCase().trim(),topic=$('#resource-topic')?.value||'All topics',collection=$('#resource-collection')?.value||'All collections';
 const found=resources.filter(r=>(topic==='All topics'||r.topic===topic)&&(collection==='All collections'||resourceCollection(r)===collection)&&`${r.title} ${r.desc} ${r.topic} ${resourceCollection(r)} ${r.credit||''} ${r.connection||''}`.toLowerCase().includes(q));
 $('#resource-count').textContent=`${found.length} resource${found.length===1?'':'s'} shown`;
 $('#resource-grid').innerHTML=found.length?found.map(r=>`<article class="card resource"><div class="meta"><span class="badge">${escapeHTML(r.topic)}</span><span class="badge ${r.collection?'educator-source':''}">${r.sourceLabel?escapeHTML(r.sourceLabel):r.collection?'EDUCATOR RESOURCE':r.internal?'STUDIO TOOL':'OFFICIAL · PUBLIC'}</span></div><h3>${escapeHTML(r.title)}</h3><p>${escapeHTML(r.desc)}</p>${r.connection?`<div class="resource-connection"><strong>Classroom connection</strong><span>${escapeHTML(r.connection)}</span></div>`:''}${r.credit?`<p class="resource-credit">${escapeHTML(r.credit)}</p>`:''}<div class="resource-bottom">${r.internal?`<a href="${r.url}">Open activity →</a>`:ext(r.url,'Open source')}<span class="format">${escapeHTML(r.type)}</span></div></article>`).join(''):'<div class="empty"><h3>No matches yet.</h3><p>Try a shorter search, “All collections,” or “All topics.”</p></div>';
}
function about(){return `<div class="shell"><div class="page-title"><p class="eyebrow">TEACHER EDITION · CONTENT &amp; PRIVACY</p><h1>Using the Studio</h1><p>A public teaching resource for Arroyo Valley High School’s Global Leadership Academy: IB ideas, education research, and classroom planning. This is not an official IB publication or a replacement for verified school programme information. The black and Vegas-gold design with blue accents is a studio interpretation, not an official school brand specification.</p></div><div class="grid2"><div class="card"><h3>What is here</h3><p>Subject pathways, DP core, MYP planning and ATL, personal-project connections, research briefs, reusable workshops, teaching summaries, and a subject-group recruitment scratchpad.</p><p>Activities and research-to-classroom suggestions are editorial adaptations, not mandated IB sequences or evidence of equal effects in every classroom. Verify current requirements with your subject guide and programme team.</p><h3>External resources</h3><p>Journals and third-party tools have their own access, account, payment, and privacy requirements. Inclusion is not school or district approval. Restricted school documents and private records are not linked here. The two staff sign-in links open separate Google Forms. They may require a school account, and attendance is recorded only after you submit the appropriate form. Signing into a form does not save your Studio drafts.</p></div><div class="card"><span class="help-status">CURRENT TOOL STATUS · NO ACCOUNT SAVES</span><h3>Your notes stay in this tab</h3><p>Organizer text, choices, and checklist progress remain in memory in this browser tab. The app does not send them to a server or save them in browser storage. Reloading or closing clears them.</p><p>Download or print your notes to keep them. A download creates a file on your device; it does not upload to Drive, post to Classroom or send anything to your facilitator. Do not enter student names, grades, cases, personal data, or confidential links. Use approved school systems for those records.</p><p>The AI prompt tools copy or download text; they do not send a request to an AI service. This app adds no analytics, external fonts or student-data integration. The hosting provider may process ordinary web requests under its policies.</p></div></div><p>${ext(urls.school,'Official Global Leadership Academy page')} · Confirm local courses, policies, and deadlines with the programme team.</p></div>`;}

function privacyNote(){return `<p class="privacy-inline">Draft in this tab only. Nothing is submitted to your facilitator or saved to a school account. Download or print before reloading or closing. No student or confidential information.</p>`;}
function startContent(){return `<p class="lead">Work on one task from a unit you are teaching now. By the end, keep a revision you can use, a clearer IB connection, and a plan to see what happens.</p><div class="prompt"><h3>Today’s intention</h3><p>I can explain the programme responsibility behind my task, make one ATL practice visible, and use a question about knowledge to deepen the learning.</p></div><div class="task-grid">${tile('01 / OPEN','Bring the actual task','Have your unit plan, student directions, and current subject guide or criteria beside you. Preserve the original.')}${tile('02 / NOTICE','Identify the useful change','Where is student thinking hard to see? Choose one question, direction, criterion, or checkpoint to improve.')}</div><details><summary>Facilitator: first five minutes</summary><div><p>Introduce the intention, invite a brief notice/wonder, ask pairs to identify a question, evidence, and ATL practice, then hear one sample response.</p><p>No school dataset is embedded. If using a dated, approved aggregate snapshot, name its date, denominator, and limits. Do not infer current risk or cause, and do not show named records.</p></div></details>${field('unit','Which current unit and task will you use?','Course / unit / task title. Keep student information out.',2)}${field('learning','What should students understand or be able to do?','Use student-friendly language, while keeping the intended challenge.',2)}<div class="note"><strong>Keep one thread.</strong> Use the same task through the core workshop. The technology lab is an optional extension, not a scheduled afternoon assignment.</div>`;}
const claims=[{text:'Every Site B reading is higher than every Site A reading.',correct:true,feedback:'Supported. B ranges from 7 to 9 mg/L and A from 2 to 3 mg/L. This compares only the fictional readings supplied.'},{text:'These readings establish that Site B is unsafe.',correct:false,feedback:'Not established. We have no applicable safety standard, sampling context, or quality checks. A higher value alone does not establish safety.'},{text:'Fertilizer caused the difference between the sites.',correct:false,feedback:'Not established. The table contains no evidence about the source or cause of the difference.'}];
function claimHTML(c,i){const a=state.answers[i];return `<div class="check-claim"><p><strong>${i+1}.</strong> ${c.text}</p><div class="choice-row" role="group" aria-label="Evaluate claim ${i+1}"><button class="choice" data-claim="${i}" data-value="true" aria-pressed="${a===true}">Supported by these data</button><button class="choice" data-claim="${i}" data-value="false" aria-pressed="${a===false}">Not established</button></div><div id="feedback-${i}" role="status">${a===undefined?'':feedbackHTML(c,a)}</div></div>`;}
function feedbackHTML(c,a){return `<div class="feedback ${a===c.correct?'':'retry'}"><strong>${a===c.correct?'That distinction works.':'Recheck the evidence.'}</strong> ${c.feedback}</div>`;}
function evidenceContent(){return `<p class="lead">Try the learning routine before adapting it. What can we justify, and what would we need to know next?</p><table class="data-table"><caption>Fictional teaching example · Nitrate readings in mg/L · Not a water-safety assessment</caption><thead><tr><th scope="col">Site</th><th scope="col">Reading 1</th><th scope="col">Reading 2</th><th scope="col">Reading 3</th></tr></thead><tbody><tr><th scope="row">A</th><td>2</td><td>3</td><td>2</td></tr><tr><th scope="row">B</th><td>8</td><td>9</td><td>7</td></tr></tbody></table><div class="prompt"><h3>Recommend a next step.</h3><p>Which site merits further testing? Identify a pattern and one limitation. Offer a provisional recommendation, then invite a partner to challenge it.</p></div><p class="eyebrow">ILLUSTRATIVE FLAWED RESPONSE</p><blockquote class="claim">“Site B is unsafe because fertilizer caused contamination.”</blockquote><p class="small muted">Deliberately written for critique, not output from a live AI tool. These data establish neither safety nor cause.</p>${claims.map(claimHTML).join('')}<details><summary>Reveal a defensible revision after discussing</summary><div><p>Prioritize Site B for further testing because its three readings are higher than Site A’s. Use comparable sampling conditions and investigate context. Three readings per site do not establish water safety or explain the cause of the difference.</p><p><strong>Notice the work:</strong> retain the supported pattern, remove the invented conclusion, name a limitation, and explain the revision.</p></div></details>${field('limit','What limit or assumption changed your recommendation?','What additional evidence would help? Transfer this move to your own subject.',2)}<p class="small muted">Timing:  model the inquiry;  critique claims;  self-check evidence, limitation, and revision. A paper discussion works equally well.</p>`;}
function responsibilityDetail(){if(state.programme==='MYP')return `<h3>MYP: locate the unit’s anchors.</h3><p>Check the current unit planner: concepts, global context, subject-group objectives, and the relevant year-level criteria. Name the ATL action students will practice. Questions about evidence or perspective can support inquiry; they are not a new formal TOK requirement.</p><p>${ext(urls.myp,'Official MYP curriculum')} · ${ext(urls.mypAssessment,'Official MYP assessment')}</p>`;if(state.programme==='DP')return `<h3>DP: connect subject learning and knowledge.</h3><p>Check the current syllabus focus, SL/HL level, assessment session, subject aims, and relevant assessment objective or component. Verify coursework authenticity, permitted feedback, and deadlines with the current guide and coordinator. Add an appropriate TOK connection about knowledge in your discipline. The formal TOK course is a DP core component; this task remains a subject task unless it is specifically a TOK assessment.</p><p>${ext(urls.dp,'Official DP curriculum')} · ${ext(urls.tok,'Official TOK overview')}</p>`;return `<h3>AP / other: retain your existing expectations.</h3><p>Use your current course standards and assessment criteria. Adopt a useful inquiry routine, explicit learning skill, or TOK-inspired question without presenting it as a new formal IB requirement.</p><p>${ext(urls.teaching,'Explore the IB teaching approach')}</p>`;}
function responsibilitiesContent(){return `<p class="lead">Build confidence by identifying the actual requirement and the source behind it. Avoid adding a label without changing what students do.</p><div class="practice-tabs" role="group" aria-label="Programme"><button data-programme="MYP" aria-pressed="${state.programme==='MYP'}">MYP</button><button data-programme="DP" aria-pressed="${state.programme==='DP'}">DP</button><button data-programme="Other" aria-pressed="${state.programme==='Other'}">AP / other courses</button></div><div class="practice-content" id="programme-detail">${responsibilityDetail()}</div><div class="task-grid">${tile('ASK','What is required here?','Point to the subject aim, objective, criterion, or course expectation that this task serves.')}${tile('CHECK','What can I actually observe?','Name a student explanation, choice, product, or revision that would show the learning.')}</div>${field('responsibility','What programme reference will guide this task?','Note the subject guide / objective / criterion and any question to verify with the coordinator.',3)}<details><summary>Use the distinction: a subject question and a knowledge question</summary><div><p><strong>Subject question:</strong> Which site has higher readings?<br><strong>Knowledge question:</strong> When is this evidence sufficient to justify a conclusion?</p><p>Other examples: How does translation affect meaning? What can a model help us know, and what does it leave out? Connect the question to the real content of your unit.</p></div></details><div class="note"><strong>Guided check.</strong> Have partners show the evidence they would accept, one ATL action they would teach, and one assumption a knowledge question could expose.</div>`;}
function studioContent(){return `<div class="note"><strong>Want a worked example?</strong> <a href="#examples">Open a daily lesson with prompts, activities and evidence →</a></div><p class="lead">Protect these 20 minutes for building. Keep your current unit and standards. Revise one task so the learning, evidence, and student thinking are easier to see.</p><div class="prompt"><h3>Your output</h3><p>A revised task in your existing course format, plus a clear evidence check, one taught ATL practice, and a meaningful question about knowledge.</p></div><div class="two-fields">${field('question','1. What will students investigate?','Write a question that calls for thinking with your unit content.',3)}${field('evidence','2. What evidence will show learning?','Name the student work or talk and one applicable success criterion.',3)}</div>${field('revision','3. Revise the student directions.','Keep the original in your unit file. Ask students to use evidence, offer an explanation or design, respond to feedback, and revise.',4)}<h3 style="margin-top:30px">Choose one ATL practice.</h3><div class="skill-buttons">${skillButtons()}</div><div class="skill-detail" id="skill-detail">${skillDetail()}</div>${field('atl','4. What will you explicitly teach and observe?','For example: model how to distinguish a claim from an assumption; listen for a reasoned challenge.',2)}${field('tok','5. What question about knowledge belongs here?','Keep it connected to the subject. For MYP or other courses, use it as a thinking lens, not a formal DP TOK requirement.',2)}<details><summary>A quick quality check before you move on</summary><div><p>Can students tell what they are learning? Does the evidence fit your actual criterion? Does the ATL practice require a visible action? Does the knowledge question examine evidence, perspective, methods, or justification? Is the task still appropriately challenging and accessible?</p></div></details>`;}
function challengeContent(){return `<p class="lead">Trade tasks, not polished presentations. Give one challenge that can improve the explanation, design, or task.</p><div class="task-grid">${tile('','Locate the purpose','Read the inquiry question and criterion. Explain what the task asks students to learn.')}${tile('','Trace the evidence','Find the evidence students must use. Challenge one assumption or unsupported claim.')}${tile('','Check ATL and the knowledge question','Can you see the skill in action? Does the knowledge question deepen the subject thinking?')}${tile('','Choose the useful revision','The author names one change and explains why it improves the task.')}</div><div class="prompt"><h3>Try a reasoned challenge.</h3><p>“Your task asks students to ____. I can see evidence of ____ when they ____. I wonder whether ____. What would change if ____?”</p></div>${field('feedback','What did your partner challenge, and how will you respond?','Record the feedback that changes the thinking, rather than general praise.',4)}<div class="note"><strong>Look for learning.</strong> A partner should be able to explain how their feedback helps a learner improve, not just how the task looks.</div>`;}
function commitContent(){return `<p class="lead">Make the change, name the reason, and choose a classroom trial. The goal is one usable next step.</p><div class="task-grid">${tile('','Revise and share','Update the task in your own unit file. Explain the evidence or reasoning behind one change.')}${tile('','Leave with a trial','Name the teaching date, what you will look for, and when you will review it with a colleague.')}</div>${field('change','What changed, and why?','Point to the task, criterion, evidence, ATL action, or knowledge question.',3)}${field('trial','What is your classroom trial and review plan?','Teaching date · evidence you will review · review date or partner. Keep student records in the approved system.',3)}${field('confidence','Where are you clearer, and what still needs checking?','One MYP/DP responsibility you can now explain; one question for the programme team.',2)}<div class="callout-big"><h3>Finish the core workshop.</h3><p>Download a plain-text organizer or print your notes. You can stop here or choose an optional extension. This page does not save them after you close or reload the tab.</p><div class="actions"><button class="btn light" data-action="download">Download my organizer ↓</button><button class="btn gold" data-action="print">Print my organizer</button><a class="text-link" href="#pd/nov10-pd">Return to November 10 session →</a></div></div><details><summary>Preview my organizer</summary><div>${organizerSummary()}</div></details>`;}
const practices=[
 {title:'Criteria & useful feedback',goal:'Strengthen an explanation without replacing the learner’s thinking.',inquiry:'What makes this explanation supported?',atl:'Thinking + communication',tok:'What counts as evidence in this subject?',prepare:'Use your own task directions and a fictional response. Keep the actual course rubric or criteria as the authority.',prompt:'Here is my learning intention and task: [teacher-authored text]. Suggest three observable success criteria and two feedback questions that preserve the learning goal. Flag ambiguity. Do not assign grades, invent standards, or supply a finished student answer.',routine:'Students make a first attempt independently. A partner uses teacher-checked criteria to identify a strength and ask a question. Students revise and explain the change.',check:'Reject invented standards, extra requirements, and feedback that removes the thinking. AI suggestions are drafts; teachers decide what fits.',paper:'Use teacher-written criteria, a fictional response, and partner questions. Keep the first attempt, feedback, and revision.'},
 {title:'Language access, same challenge',goal:'Make directions more accessible while keeping the intended thinking.',inquiry:'How can we make the task clearer without changing its meaning?',atl:'Research + communication',tok:'How does language shape what we understand?',prepare:'Choose a teacher-authored or permitted paragraph. Specify the language, intended proficiency, and essential terms. Keep the original.',prompt:'Adapt these directions for [language/proficiency], preserving the same task and required thinking. Retain and explain [key terms]. Put the original beside the adaptation. Flag words whose meaning may change. Do not invent facts or remove the evidence requirement.',routine:'Compare original and reviewed versions. Ask learners to explain the task in their own words, then complete the same core work with a glossary or sentence frame if useful.',check:'A qualified speaker verifies meaning, register, and technical terms. An unverified translation remains a draft, not an accommodation decision.',paper:'Use a verified glossary, a teacher-written scaffold, and partner paraphrasing. Check the same learning evidence.'},
 {title:'Storyboard & human authorship',goal:'Use alternatives to sharpen human design choices.',inquiry:'How can a design communicate an idea accurately for its audience?',atl:'Thinking + self-management',tok:'How does a representation shape knowledge?',prepare:'Create a fictional brief, such as a 30-second animation explaining why data need context. Include audience and criteria. Use no student images, voices, or personal stories.',prompt:'Using this fictional brief, propose two contrasting storyboard approaches. For each, list the audience, sequence, one design risk, and a question a student should decide. Do not create the final script or finished artwork. Brief: [teacher-authored brief].',routine:'Students sketch their own idea first, critique alternatives, and make a final storyboard with a design rationale and a brief record of assistance.',check:'Check facts, omissions, stereotypes, accessibility, and asset rights. Preserve the learner’s decision-making and authorship.',paper:'Compare two teacher-written alternatives and sketch on paper. Explain one rejected option and one justified revision.'}
];
function practiceContent(){const p=practices[state.practice];return `<h3>${p.title}</h3><p>${p.goal}</p><p><strong>Inquiry:</strong> ${p.inquiry}<br><strong>ATL:</strong> ${p.atl}<br><strong>TOK lens:</strong> ${p.tok}</p><h4>Prepare</h4><p>${p.prepare}</p><h4>Optional prompt for an approved tool</h4><p class="prompt-text">${p.prompt}</p><h4>Classroom routine</h4><p>${p.routine}</p><h4>Teacher review</h4><p>${p.check}</p><h4>Equivalent no-AI route</h4><p>${p.paper}</p>`;}
const checks=['The learning goal and students’ independent thinking are clear.','The district approves the tool, account, and intended use, including any student access.','I am using teacher-authored or permitted materials with no student or confidential data.','A teacher verifies accuracy, language, bias, accessibility, and fit.','The task states permitted assistance and disclosure expectations, with a no-AI route.','Teachers retain assessment and support decisions; AI does not assign grades or choose interventions.'];
function technologyContent(){return `<p class="lead">Extend the same task. Start with the learning purpose, then decide whether technology helps. A live AI tool is optional.</p><div class="note"><strong>Default to the prepared examples or paper route.</strong> The current district-approved tool list has not been verified. Do not create new accounts or enter student information for this workshop.</div><p class="small muted">Looking for tool ideas? <a class="text-link" href="#resources/nick">Browse Nick’s shared toolkit →</a>. These are external educator resources for review, not a district-approved tool list.</p><details><summary>A flexible lab plan</summary><div><p>Clarify safeguards and purpose → choose a card → build → peer review → plan a trial → share.</p><p>Use the same task from the core workshop. Keep the learner’s independent decisions and the teacher’s review visible.</p></div></details><h3 style="margin-top:26px">Before any classroom use</h3><ul class="checklist">${checks.map((c,i)=>`<li><label><input type="checkbox" data-check="${i}" ${state.checks[i]?'checked':''}><span>${c}</span></label></li>`).join('')}</ul><p class="small muted">Checking these boxes records your review; it does not approve a tool or replace district policy. ${ext(urls.ai,'IB AI guidance')} · ${ext(urls.integrity,'Academic integrity')}</p><div class="practice-tabs" role="group" aria-label="Choose a practice card">${practices.map((p,i)=>`<button data-practice="${i}" aria-pressed="${state.practice===i}">${i+1}. ${['Feedback','Language access','Storyboard'][i]}</button>`).join('')}</div><div class="practice-content" id="practice-detail">${practiceContent()}</div>${field('tech','What is the technology’s job in your task?','What thinking and authorship stay with students? Why is this better than the simplest no-tech option?',3)}${field('review','What did you verify, change, or reject?','Name the source or professional judgment you used. No live tool is required.',3)}${field('permissions','What will the classroom directions say?','Permitted assistance · independent work · disclosure / citation · equivalent no-AI route.',3)}<details><summary>A disclosure frame to adapt</summary><div><p>“I used [tool or resource] for [permitted purpose]. I checked [claim or suggestion] against [source]. I changed or rejected [item]. My own contribution was [work].”</p><p>Follow current assignment, school, and programme requirements. This frame is a workshop tool, not a substitute for those requirements.</p></div></details>`;}
function supportContent(){return `<div class="note"><a href="#supports">Open student supports and fictional data practice →</a></div><p class="lead">Use evidence carefully to choose a helpful classroom response. Keep individual cases and records in the school’s existing restricted system.</p><div class="note"><strong>No student dataset is hosted here.</strong> If the team uses an approved, dated aggregate snapshot separately, check the cohort, denominator, course scope, missing marks, and date before drawing conclusions. A historical pattern is not a current diagnosis.</div><div class="task-grid">${tile('NOTICE','Describe what is actually there','State a pattern without ranking groups or inventing a cause. Separate what you see from what you infer.')}${tile('VERIFY','Check the context','Confirm current evidence, missing information, and the student perspective through authorized school channels.')}${tile('SUPPORT','Choose a low-risk next step','Examples: clearer directions, a planning checkpoint, a feedback-and-revision opportunity, or an explicit help-seeking routine.')}${tile('REVIEW','Make follow-through possible','Record the owner, date, and review evidence in the existing restricted log, not on this site.')}</div><div class="prompt"><h3>Discussion stems</h3><p>“We notice ____.”<br>“We do not yet know ____.”<br>“Before acting, we need to check ____.”<br>“A classroom support we can try is ____, and we will look for ____.”</p></div>${field('support','What non-identifying classroom support will you try?','Record only the general teaching move and review evidence. No names, cases, marks, or confidential links.',4)}<h3 style="margin-top:28px">Continue the learning.</h3><p class="small muted">Continue programme and course work, confirm your classroom trial, and identify support needed.</p><div class="actions"><button class="btn" data-action="download">Download my organizer ↓</button><button class="btn secondary" data-action="print">Print my organizer</button></div>`;}
const contentFns=[startContent,evidenceContent,responsibilitiesContent,studioContent,challengeContent,commitContent,technologyContent,supportContent];
function workshop(id){let idx=steps.findIndex(s=>s.id===id);if(idx<0)idx=0;const s=steps[idx];return `<div class="workshop-shell"><div class="workshop-heading"><div><div class="eyebrow-line"><a class="small text-link" href="#pd/nov10-pd">← November 10 session</a><span class="badge draft">REUSABLE WORKSHOP</span></div><h1>Make thinking visible</h1><p>Six core activities · about 60 minutes, with optional extensions</p></div><div class="workshop-tools"><button class="btn secondary small" data-action="focus" aria-pressed="${state.focus}">${state.focus?'Exit focus view':'Focus view'}</button><button class="btn secondary small" data-action="download">Download notes ↓</button><button class="btn secondary small" data-action="print">Print notes</button></div></div><div class="workshop-scope"><strong>Tuesday, November 10: proposed workshop sequence.</strong> The pull-out day is confirmed; the facilitator must confirm this workshop’s time and room. The durations below are planning suggestions. <a href="#pd/nov10-pd">Check the meeting outline →</a></div><div class="workshop-grid"><aside class="activity-nav" aria-label="Workshop activities"><ol>${steps.map((x,i)=>`${i===0?'<li class="activity-group-label" role="presentation">Core workshop · six activities</li>':i===6?'<li class="activity-group-label" role="presentation">Optional extensions</li>':''}<li><a class="step-link" href="#workshop/${x.id}" ${i===idx?'aria-current="step"':''}><span class="step-number">${state.done.has(x.id)?'✓':String(i+1).padStart(2,'0')}</span><span>${x.title}<small>${i>=6?'Optional · ':''}${x.sub}</small></span></a></li>`).join('')}</ol><div class="progress-box"><span id="progress-text">${state.done.size} of ${steps.length} activities marked complete</span><div class="progress-track" role="progressbar" aria-label="Workshop completion" aria-valuemin="0" aria-valuemax="8" aria-valuenow="${state.done.size}"><span style="width:${state.done.size/8*100}%"></span></div><span>Personal progress only. Extensions are optional.</span></div><div class="timer"><div><label for="timer-minutes">Optional activity timer</label><select id="timer-minutes"><option value="5">5 minutes</option><option value="10">10 minutes</option><option value="20">20 minutes</option></select></div><output id="timer-output" aria-label="Timer remaining">${timerText()}</output><div class="timer-actions"><button data-action="timer-toggle" id="timer-toggle">${timerHandle?'Pause':'Start'}</button><button data-action="timer-reset">Reset</button></div></div></aside><section class="activity-panel" aria-labelledby="activity-title"><p class="eyebrow">ACTIVITY ${String(idx+1).padStart(2,'0')} / ${s.sub}</p><h2 id="activity-title" tabindex="-1">${s.title==='Revise the task'?'Revise your task':s.title==='Choose your unit'?'Choose a current unit and task':s.title==='Check programme guidance'?'Check the programme requirements':s.title==='Test a claim'?'What can these data tell us?':s.title==='Invite a challenge'?'Ask a colleague for feedback':s.title==='Revise & try'?'Plan the classroom trial':s.title==='Technology lab'?'Choose a tool for the task':'Plan support and review'}</h2><div class="activity-meta"><span><b>OUTPUT</b> ${s.goal}</span><span><b>ATL</b> ${s.atl}</span></div><p class="small muted"><strong>Knowledge question:</strong> ${s.tok}</p>${privacyNote()}${contentFns[idx]()}<div class="activity-bottom">${idx?`<a class="btn secondary" href="#workshop/${steps[idx-1].id}">← Previous</a>`:'<span></span>'}<label><input type="checkbox" data-complete="${s.id}" ${state.done.has(s.id)?'checked':''}>Mark this activity complete</label>${idx<steps.length-1?`<a class="btn" href="#workshop/${steps[idx+1].id}">${idx===5?'Optional technology lab':idx===6?'Optional support activity':'Next activity'} →</a>`:'<a class="btn" href="#pd">Back to PD &amp; PLC →</a>'}</div></section></div></div>`;}
let timerSeconds=300,timerDuration=300,timerHandle=null;
function timerText(){return `${Math.floor(timerSeconds/60).toString().padStart(2,'0')}:${(timerSeconds%60).toString().padStart(2,'0')}`;}
function updateTimer(){if($('#timer-output'))$('#timer-output').textContent=timerText();if($('#timer-toggle'))$('#timer-toggle').textContent=timerHandle?'Pause':'Start';}
function toggleTimer(){if(timerHandle){clearInterval(timerHandle);timerHandle=null;}else{if(timerSeconds<=0)timerSeconds=timerDuration;timerHandle=setInterval(()=>{timerSeconds=Math.max(0,timerSeconds-1);if(timerSeconds===0){clearInterval(timerHandle);timerHandle=null;toast('Timer finished. Pause, reflect, and choose your next step.');}updateTimer();},1000);}updateTimer();}
function organizerSummary(){return Object.entries(noteLabels).map(([id,label])=>`<div class="summary-item"><h4>${label}</h4><p>${escapeHTML(state.notes[id]||'Not recorded yet.')}</p></div>`).join('');}
function notesText(){return `AVHS IB LEARNING STUDIO\nCurrent-unit workshop\nPersonal organizer. No student or confidential information.\nProgramme selected: ${state.programme}\n\n`+Object.entries(noteLabels).map(([id,label])=>`${label.toUpperCase()}\n${state.notes[id]||'[Not recorded]'}\n`).join('\n')+`\nWorkshop URL: ${location.origin}${location.pathname}#pd\nActivity sequence is a workshop adaptation, not an official IB requirement.\n`;}
function downloadNotes(){const blob=new Blob([notesText()],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='AVHS-current-unit-organizer.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Your organizer download was requested. Check your browser downloads.');}
function printNotes(){$('#print-area').innerHTML=`<h1>My current-unit organizer</h1><p class="print-meta">AVHS IB Learning Studio · Programme: ${escapeHTML(state.programme)}<br>Personal working notes. Keep student and confidential information out.</p>`+Object.entries(noteLabels).map(([id,label])=>`<div class="print-block"><h3>${label}</h3><p>${escapeHTML(state.notes[id]||'________________________________________________________________\n________________________________________________________________')}</p></div>`).join('');window.print();}
let toastTimeout;function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function bind(){const main=$('#legacy-main');main.addEventListener('input',e=>{if(e.target.dataset.note)state.notes[e.target.dataset.note]=e.target.value;if(e.target.id==='resource-search')updateResources();});main.addEventListener('change',e=>{if(e.target.id==='resource-topic'||e.target.id==='resource-collection')updateResources();if(e.target.dataset.check!==undefined)state.checks[e.target.dataset.check]=e.target.checked;if(e.target.dataset.complete){const id=e.target.dataset.complete;if(e.target.checked)state.done.add(id);else state.done.delete(id);$('#progress-text').textContent=`${state.done.size} of ${steps.length} activities marked complete`;$('.progress-track').setAttribute('aria-valuenow',state.done.size);$('.progress-track span').style.width=state.done.size/8*100+'%';const i=steps.findIndex(s=>s.id===id);$(`.step-link[href="#workshop/${id}"] .step-number`).textContent=state.done.has(id)?'✓':String(i+1).padStart(2,'0');}if(e.target.id==='timer-minutes'){timerDuration=Number(e.target.value)*60;timerSeconds=timerDuration;if(timerHandle){clearInterval(timerHandle);timerHandle=null;}updateTimer();}});main.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.skill){state.skill=d.skill;$$('[data-skill]').forEach(x=>x.setAttribute('aria-pressed',x.dataset.skill===state.skill));$('#skill-detail').innerHTML=skillDetail();}if(d.claim!==undefined){const i=Number(d.claim),v=d.value==='true';state.answers[i]=v;$$(`[data-claim="${i}"]`).forEach(x=>x.setAttribute('aria-pressed',x.dataset.value===d.value));$(`#feedback-${i}`).innerHTML=feedbackHTML(claims[i],v);}if(d.programme){state.programme=d.programme;$$('[data-programme]').forEach(x=>x.setAttribute('aria-pressed',x.dataset.programme===state.programme));$('#programme-detail').innerHTML=responsibilityDetail();}if(d.practice!==undefined){state.practice=Number(d.practice);$$('[data-practice]').forEach(x=>x.setAttribute('aria-pressed',Number(x.dataset.practice)===state.practice));$('#practice-detail').innerHTML=practiceContent();}if(d.action==='nick-collection'){$('#resource-collection').value='Nick’s shared toolkit';$('#resource-topic').value='All topics';$('#resource-search').value='';updateResources();$('#resource-search').focus({preventScroll:true});$('#resource-search').scrollIntoView({block:'center',behavior:'auto'});}if(d.action==='download')downloadNotes();if(d.action==='print')printNotes();if(d.action==='focus'){state.focus=!state.focus;document.body.classList.toggle('focus-mode',state.focus);b.setAttribute('aria-pressed',state.focus);b.textContent=state.focus?'Exit focus view':'Focus view';}if(d.action==='timer-toggle')toggleTimer();if(d.action==='timer-reset'){if(timerHandle)clearInterval(timerHandle);timerHandle=null;timerSeconds=timerDuration;updateTimer();}});}

export function mountLegacy(host,route,part){
 host.innerHTML='<div id="legacy-main"></div>';
 document.body.classList.toggle('focus-mode',state.focus&&route==='workshop');
 const page=route==='workshop'?workshop(part):({ib,pd,resources:resourcePage,about}[route]||ib)();
 $('#legacy-main').innerHTML=page;
 if(route==='resources'){if((part==='aet'||part==='nick')&&$('#resource-collection'))$('#resource-collection').value='Nick’s shared toolkit';updateResources();}
 if(route==='workshop'&&$('#timer-minutes'))$('#timer-minutes').value=String(timerDuration/60);
 bind();
 return ()=>{if(timerHandle){clearInterval(timerHandle);timerHandle=null;}document.body.classList.remove('focus-mode');host.innerHTML='';};
}
window.addEventListener('beforeunload',e=>{if(Object.values(state.notes).some(v=>v.trim())){e.preventDefault();e.returnValue='';}});
